package proto

import (
	"os"
	"regexp"
	"strings"
	"testing"
)

// protocGenEsRuntimeVersion is the protoc-gen-es version the companion image
// must bake. It has to match the @bufbuild/protobuf runtime version consumers
// pin (currently 2.11.0): the generator emits the
// `// @generated by protoc-gen-es v<version>` header and codegen shaped for a
// specific runtime surface, so a companion whose es diverges from a repo's
// pinned runtime makes companion output disagree with committed *_pb.ts forever
// (sync-drift). Bump this only in lockstep with the ecosystem runtime.
const protocGenEsRuntimeVersion = "2.11.0"

// The proto companion image has two build definitions (Dockerfile and
// flake.nix) for the same ghcr.io/codefly-dev/proto tag. Both must bake the same
// pinned es, or the image's behaviour depends on which builder published it.
var (
	protocGenEsDockerfilePin = regexp.MustCompile(`@bufbuild/protoc-gen-es@([0-9]+\.[0-9]+\.[0-9]+)`)
	protocGenEsFlakePin      = regexp.MustCompile(`protocGenEsVersion = "([0-9]+\.[0-9]+\.[0-9]+)"`)
)

func TestDockerfilePinsProtocGenEsToRuntimeVersion(t *testing.T) {
	assertPinnedToRuntime(t, "Dockerfile", protocGenEsDockerfilePin)
}

func TestFlakePinsProtocGenEsToRuntimeVersion(t *testing.T) {
	assertPinnedToRuntime(t, "flake.nix", protocGenEsFlakePin)
}

// facadeBinaries are the plugin binaries the image must expose for facade
// generation, on top of the gRPC/OpenAPI set. protoc-gen-connect-go is what the
// Go facade imports; the three protoc-gen-codefly-facade-* binaries and
// codefly-proto-strip-options are new. Both build definitions must install
// every one, or the image's behaviour depends on which builder published it.
var facadeBinaries = []string{
	"protoc-gen-connect-go",
	"protoc-gen-codefly-facade-go",
	"protoc-gen-codefly-facade-python",
	"protoc-gen-codefly-facade-ts",
	"codefly-proto-strip-options",
}

func TestDockerfileInstallsFacadePlugins(t *testing.T) {
	assertMentionsAll(t, "Dockerfile", facadeBinaries)
	// The legacy plugin name is kept for one release so the runtime repo can
	// switch off it.
	assertMentionsAll(t, "Dockerfile", []string{"protoc-gen-solution_facade"})
}

func TestFlakeInstallsFacadePlugins(t *testing.T) {
	assertMentionsAll(t, "flake.nix", facadeBinaries)
}

// TestTsFacadePinsProtoplugin keeps the TS facade plugin's protoplugin runtime
// in lockstep with protoc-gen-es: the facade imports the service schemas es
// emits, and protoplugin ships alongside es on the same release train.
func TestTsFacadePinsProtoplugin(t *testing.T) {
	content, err := os.ReadFile("facades/ts/package.json")
	if err != nil {
		t.Fatalf("read facades/ts/package.json: %v", err)
	}
	pin := regexp.MustCompile(`"@bufbuild/protoplugin":\s*"([0-9]+\.[0-9]+\.[0-9]+)"`)
	match := pin.FindSubmatch(content)
	if match == nil {
		t.Fatal("facades/ts/package.json no longer pins @bufbuild/protoplugin to an explicit version")
	}
	if got := string(match[1]); got != protocGenEsRuntimeVersion {
		t.Fatalf("facades/ts pins @bufbuild/protoplugin %s, but the ecosystem runtime is %s", got, protocGenEsRuntimeVersion)
	}
}

// TestBuildDefinitionsInstallGrpcioToolsInRuntime guards the Python protobuf
// generator inside the image. grpc_tools is not a plugin binary that
// assertMentionsAll would catch: it is a Python module, reached as
// `python -m grpc_tools.protoc`, and a consumer generating Python stubs from a
// contract has no other way to produce them.
//
// The Dockerfile mentions grpcio-tools twice and only one of them counts. The
// builder stage installs it into a venv that is never COPYed; the runtime stage
// builds its own /venv. So the image can carry a /venv that exists, answers to
// /venv/bin/python, and still has no grpc_tools — which is what shipped in
// 0.0.14. Asserting on the runtime install specifically, rather than on the
// string appearing anywhere in the file, is the difference between this test
// passing and meaning it.
func TestBuildDefinitionsInstallGrpcioToolsInRuntime(t *testing.T) {
	dockerfile, err := os.ReadFile("Dockerfile")
	if err != nil {
		t.Fatalf("read Dockerfile: %v", err)
	}
	// Scope to the runtime stage: the builder installs grpcio-tools too, on a
	// line of the same shape, into a venv that is never copied. Matching the
	// whole file would pass on an image that ships no grpc_tools at all.
	stages := regexp.MustCompile(`(?m)^FROM `).FindAllStringIndex(string(dockerfile), -1)
	if len(stages) < 2 {
		t.Fatalf("Dockerfile has %d FROM stages, expected the builder + runtime pair; this guard can no longer tell them apart", len(stages))
	}
	runtimeStage := string(dockerfile)[stages[len(stages)-1][0]:]
	runtimeInstall := regexp.MustCompile(`/venv/bin/pip install[^\n]*\bgrpcio-tools\b`)
	if !runtimeInstall.MatchString(runtimeStage) {
		t.Error("Dockerfile does not install grpcio-tools into the RUNTIME /venv; `python -m grpc_tools.protoc` will not exist in the image even though the builder stage installs it into a venv that is never COPYed (this is what shipped in 0.0.14)")
	}

	flake, err := os.ReadFile("flake.nix")
	if err != nil {
		t.Fatalf("read flake.nix: %v", err)
	}
	// Both build definitions publish the same tag, so the facade python must
	// carry the same module.
	facadePython := regexp.MustCompile(`python3\.withPackages \(ps: \[[^\]]*\bps\.grpcio-tools\b[^\]]*\]\)`)
	if !facadePython.Match(flake) {
		t.Error("flake.nix does not give the facade python grpcio-tools; the nix-built image would lack grpc_tools while the Docker-built one has it, so behaviour would depend on which builder published the tag")
	}
}

func assertMentionsAll(t *testing.T, file string, needles []string) {
	t.Helper()
	content, err := os.ReadFile(file)
	if err != nil {
		t.Fatalf("read %s: %v", file, err)
	}
	for _, needle := range needles {
		if !strings.Contains(string(content), needle) {
			t.Errorf("%s does not install %q", file, needle)
		}
	}
}

func assertPinnedToRuntime(t *testing.T, file string, pin *regexp.Regexp) {
	t.Helper()
	content, err := os.ReadFile(file)
	if err != nil {
		t.Fatalf("read %s: %v", file, err)
	}
	match := pin.FindSubmatch(content)
	if match == nil {
		t.Fatalf("%s no longer pins protoc-gen-es to an explicit version", file)
	}
	if got := string(match[1]); got != protocGenEsRuntimeVersion {
		t.Fatalf("%s pins protoc-gen-es %s, but the ecosystem runtime is %s; the generator and runtime must move together (see issue #83)", file, got, protocGenEsRuntimeVersion)
	}
}

// TestTypeScriptTemplateUsesTheBakedProtocGenEs keeps the generator a consumer's
// bindings come from inside the guarantee the rest of this file makes. A
// remotely-resolved es entry is a second pin that nothing holds to
// protocGenEsRuntimeVersion — the template generated with v2.2.3 for as long as
// the image baked 2.11.0 — and it is resolved over the network, so generation
// depends on the BSR being reachable and under its rate limit.
//
// The template is version v2, where the baked plugin is `local: protoc-gen-es`
// and a remote one is `remote:` rather than v1's `name:` and `plugin:`. Both
// remote spellings are rejected: the format changed, the reason did not.
func TestTypeScriptTemplateUsesTheBakedProtocGenEs(t *testing.T) {
	content, err := os.ReadFile("templates/typescript/buf.gen.yaml.tmpl")
	if err != nil {
		t.Fatalf("read templates/typescript/buf.gen.yaml.tmpl: %v", err)
	}
	if match := regexp.MustCompile(`(?:plugin|remote):\s*buf\.build/bufbuild/es\S*`).Find(content); match != nil {
		t.Errorf("the TypeScript template resolves es remotely (%s); use the image's own `local: protoc-gen-es`, which companion_plugins_test.go pins to %s", match, protocGenEsRuntimeVersion)
	}
	if !regexp.MustCompile(`(?m)^\s*-\s*local:\s*protoc-gen-es\s*$`).Match(content) {
		t.Error("the TypeScript template no longer runs the image's own protoc-gen-es")
	}
}
